 const chars=cur?cur.text.length:0;const lines=cur?cur.uids.length:0;
 if(!cur||lines>=70||chars>=9000||(cur.last!==u.file&&(lines>=30||chars>=4000))){n++;cur={chunk_id:'C'+n,text:'',uids:[],last:u.file};chunks.push(cur);}
 cur.text+=(cur.text?'\n':'')+u.uid+' '+u.text;cur.uids.push(u.uid);cur.last=u.file;}
chunks.forEach(c=>delete c.last);
